package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class CiceroWorkflowTest {
    @TempDir Path temp;
    private Map<String,Object> analysis(){var a=new LinkedHashMap<String,Object>();a.put("id","coaccess");a.put("aggregation_seed",1);a.put("k",2);a.put("size_factor_normalize",true);a.put("summary_stats",List.of());a.put("model",Map.of("window",100,"power",0.75,"max_elements",200));a.put("distance_parameter",Map.of("mode","fixed","value",2));a.put("skipped_windows_policy","retain-source-dispositions");a.put("unresolved_connections_policy","retain-source-NA");return a;}
    private Map<String,Object> raw(){var r=new LinkedHashMap<String,Object>();r.put("schema_version",1);r.put("mode","COACCESS");r.put("version","1.3.9");r.put("matrix_format","dense-tsv");r.put("coordinate_system","one-based-closed");r.put("count_units","raw-integer-counts");r.put("counts","counts");r.put("peak_metadata","peaks.tsv");r.put("cell_metadata","cells.tsv");r.put("embedding","embedding.tsv");r.put("genome","genome.tsv");r.put("numeric_metadata",List.of());r.put("binarize",false);r.put("analyses",List.of(analysis()));r.put("rscript","missing-Rscript");r.put("r_home","missing-R-home");r.put("r_libraries",List.of("missing-library"));r.put("out","result");return r;}
    private void inputs()throws IOException {Files.writeString(temp.resolve("peaks.tsv"),"peak_id\tchromosome\tstart\tend\nchr1_2_8\tchr1\t2\t8\nchr1_90_110\tchr1\t90\t110\n");Files.writeString(temp.resolve("cells.tsv"),"cell_id\n cell\"β \nNA\ncell3\n");Files.writeString(temp.resolve("embedding.tsv"),"cell_id\tx\ty\n cell\"β \t0\t0\nNA\t1\t0\ncell3\t2\t1\n");Files.writeString(temp.resolve("genome.tsv"),"chromosome\tlength\n1\t200\n");Files.writeString(temp.resolve("counts"),"peak_id\t cell\"β \tNA\tcell3\nchr1_2_8\t1\t2\t0\nchr1_90_110\t2\t0\t4\n");}
    private CiceroWorkflowInputs.Population population(Map<String,Object> r)throws IOException{return CiceroWorkflowInputs.validate(temp,CiceroWorkflowRequest.parse(r,temp));}
    @Test void literalInputsAndSourceCoordinateMappingAreExplicit()throws Exception {inputs();var p=population(raw());assertEquals(List.of(" cell\"β ","NA","cell3"),p.cells());assertEquals("1",p.peaks().get(0).sourceChromosome());assertEquals(6,p.storedEntries());assertEquals(2,p.explicitZeros());assertEquals(2,p.count(0,1,false));assertEquals(1,p.count(0,1,true));}
    @Test void countAndEmbeddingAxesCannotBeSilentlyReordered()throws Exception {inputs();Files.writeString(temp.resolve("embedding.tsv"),"cell_id\tx\ty\nNA\t1\t0\n cell\"β \t0\t0\ncell3\t2\t1\n");assertThrows(IOException.class,()->population(raw()));}
    @Test void genomicLabelsMustEncodeTheirDeclaredCoordinates()throws Exception {inputs();Files.writeString(temp.resolve("peaks.tsv"),"peak_id\tchromosome\tstart\tend\nchr1_2_8\tchr1\t3\t8\nchr1_90_110\tchr1\t90\t110\n");assertThrows(IOException.class,()->population(raw()));}
    @Test void originalChromosomeAliasesCannotBeMerged()throws Exception {inputs();Files.writeString(temp.resolve("genome.tsv"),"chromosome\tlength\n1\t200\nchr1\t200\n");assertThrows(IOException.class,()->population(raw()));}
    @Test void sparseCoordinatesAreExactAndNeverSummed()throws Exception {inputs();var r=raw();r.put("matrix_format","matrix-market");Files.writeString(temp.resolve("counts"),"%%MatrixMarket matrix coordinate real general\n2 3 4\n2 3 4\n1 2 2\n1 1 1\n2 1 2\n");assertEquals(4,population(r).storedEntries());Files.writeString(temp.resolve("counts"),"%%MatrixMarket matrix coordinate integer general\n2 3 2\n1 1 1\n1 1 2\n");assertThrows(IOException.class,()->population(r));}
    @Test void transformedNonfiniteAndFractionalCountsAreRefused()throws Exception {for(String value:List.of("NaN","Inf","NA","-1","0.5","9007199254740992")){inputs();Files.writeString(temp.resolve("counts"),"peak_id\t cell\"β \tNA\tcell3\nchr1_2_8\t"+value+"\t2\t0\nchr1_90_110\t2\t0\t4\n");assertThrows(IOException.class,()->population(raw()),value);}}
    @Test void zeroCellsAndPeakOrWindowCapacityAreRefused()throws Exception {inputs();Files.writeString(temp.resolve("counts"),"peak_id\t cell\"β \tNA\tcell3\nchr1_2_8\t1\t0\t0\nchr1_90_110\t2\t0\t4\n");assertThrows(IOException.class,()->population(raw()));inputs();var r=raw();r.put("maximum_windows",1);assertThrows(IOException.class,()->population(r));}
    @Test void originalPoliciesAndUnitsCannotBeInferred()throws Exception {for(var e:List.of(Map.entry("count_units",(Object)"TF-IDF"),Map.entry("script",(Object)"system('x')"),Map.entry("coordinate_system",(Object)"auto"),Map.entry("mode",(Object)"VERIFY"))){var r=raw();r.put(e.getKey(),e.getValue());assertThrows(IOException.class,()->CiceroWorkflowRequest.parse(r,temp));}var r=raw();var a=analysis();a.remove("unresolved_connections_policy");r.put("analyses",List.of(a));assertThrows(IOException.class,()->CiceroWorkflowRequest.parse(r,temp));}
    @Test void numericSummaryStatsCannotOverrideOriginalState()throws Exception {var reserved=raw();reserved.put("numeric_metadata",List.of("Size_Factor"));assertThrows(IOException.class,()->CiceroWorkflowRequest.parse(reserved,temp));var r=raw();var a=analysis();a.put("summary_stats",List.of("missing"));r.put("analyses",List.of(a));var invalid=r;assertThrows(IOException.class,()->CiceroWorkflowRequest.parse(invalid,temp));}
    @Test void nativeNearestAuditAdmitsTiesAndRejectsACloserOmission()throws Exception {var meter=new CiceroWorkflowAudit.Meter(10000);var tree=new CiceroWorkflowAudit.KdTree(new double[][]{{0,0},{1,0},{-1,0},{5,0}},meter);tree.audit(0,List.of(0,1),meter);tree.audit(0,List.of(0,2),meter);assertThrows(IOException.class,()->tree.audit(0,List.of(0,3),meter));}
    @Test void nativeAuditCapacityIsEnforced() {var meter=new CiceroWorkflowAudit.Meter(1);assertThrows(IllegalArgumentException.class,()->new CiceroWorkflowAudit.KdTree(new double[][]{{0,0},{1,1},{2,2}},meter));}
    @Test void zeroPeaksPreserveDeclaredMatrixDimensions()throws Exception {inputs();Files.writeString(temp.resolve("counts"),"peak_id\t cell\"β \tNA\tcell3\nchr1_2_8\t0\t0\t0\nchr1_90_110\t2\t3\t4\n");var p=population(raw());assertEquals(1,p.zeroPeaks());assertEquals(2,p.peaks().size());assertEquals(0,p.count(0,0,false));}
    @Test void nativeInterruptionIsNotIgnored(){Thread.currentThread().interrupt();try{assertThrows(IllegalStateException.class,()->new CiceroWorkflowAudit.Meter(100).spend(1));}finally{Thread.interrupted();}}
    @Test void missingRuntimeSkipsProminentlyWithoutAnAdmittedResult()throws Exception {inputs();NextflowFiles.writeJson(temp.resolve("request.json"),raw());var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();assertEquals(3,CiceroWorkflowCli.run(new String[]{"--request",temp.resolve("request.json").toString()},new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8)));var state=Monocle2DifferentialCli.read(temp.resolve("result/analysis-status.json"),1048576);assertEquals(false,state.get("result_admitted"));assertEquals("SKIP3_DEPENDENT_ANALYSIS_SKIPPED",state.get("status"));assertFalse(Files.exists(temp.resolve("result/results")));assertTrue(Files.readString(temp.resolve("result/WARNINGS.md")).contains("REQUIRED ACTION:"));assertTrue(err.toString(StandardCharsets.UTF_8).contains("SKIP3"));}
}
